const queries = ['show_widget widget inline', 'canvas', 'embed'];
const all = [];
for (const q of queries) {
  try {
    const found = await catalog.search(q);
    for (const f of found) {
      let name = String(f && (f.name || f.id || f));
      let desc = '';
      try { desc = JSON.stringify(await f.describe()).slice(0, 1200); } catch (e) { desc = 'describe failed: ' + e.message; }
      all.push({query:q, name, desc});
    }
  } catch (e) { all.push({query:q, error:e.message}); }
}
return all;

const [showWidget] = await catalog.search('show_widget');
const widget_code = `<!doctype html>
<html><head><meta charset="utf-8"><style>
  body{margin:0;font:14px system-ui,-apple-system,Segoe UI,sans-serif;background:transparent}
  .box{display:inline-flex;align-items:center;gap:8px;padding:8px;border:1px solid #ddd;border-radius:10px;background:#fff;color:#111}
  #n{min-width:1.5em;text-align:center;font-weight:700}
  button{border:1px solid #bbb;border-radius:8px;background:#f7f7f7;padding:4px 8px;cursor:pointer}
  button:active{transform:translateY(1px)}
</style></head><body>
  <div class="box"><span>Count:</span><span id="n">0</span><button id="inc">+1</button><button id="report">Report</button></div>
<script>
let count = 0;
const n = document.getElementById('n');
document.getElementById('inc').onclick = () => { count += 1; n.textContent = count; };
document.getElementById('report').onclick = () => {
  const text = 'Counter report: ' + count;
  const api = window.openclaw && window.openclaw.prompt;
  if (api && typeof api.send === 'function') api.send(text);
  else if (typeof window.sendPrompt === 'function') window.sendPrompt(text);
  else if (window.parent) window.parent.postMessage({type:'openclaw.prompt.send', text}, '*');
};
</script></body></html>`;
return await showWidget({title:'Counter', widget_code, height:70});
